// Custom Worker entry: OpenNext handles HTTP, we add a Cron handler for carrier tracking sync.
// @ts-expect-error generated by `opennextjs-cloudflare build`
import openNext from "./.open-next/worker.js";

type Env = { ASSETS: Fetcher } & Record<string, unknown>;

export default {
  fetch: openNext.fetch,
  async scheduled(_event: ScheduledController, env: Env, ctx: ExecutionContext) {
    // Call our own route handler so the sync runs in the full app runtime.
    const req = new Request("https://internal/api/cron/sync-tracking", {
      method: "POST",
      headers: { "x-cron": "1" },
    });
    ctx.waitUntil(openNext.fetch(req, env, ctx));
  },
};

// Durable Object classes OpenNext's bundle expects to be exported (unused unless bound).
// @ts-expect-error generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
